        F.W[E.u('Z',p),u]+=-K6; F.b[u]=1+K6
        u=F.u('SA',p)
        for q in nb(p): F.W[E.u('FM',q),u]-=1
        F.W[E.u('Z',p),u]+=-Ksa; F.b[u]=1+2*Ksa
        u=F.u('PL',p); F.W[E.u('PL',p),u]=1
